function validate([trees]) {
  if (!Array.isArray(trees) || trees.length < 1 || trees.length > 3000) return 'trees needs 1 to 3000 positions.';
  const seen = new Set();
  for (const tree of trees) {
    if (!Array.isArray(tree) || tree.length !== 2) return 'Each tree is a pair [x, y].';
    const [x, y] = tree;
    if (!Number.isInteger(x) || !Number.isInteger(y) || x < 0 || x > 100 || y < 0 || y > 100) return 'Coordinates are whole numbers from 0 to 100.';
    if (seen.has(x * 101 + y)) return 'All tree positions must be different.';
    seen.add(x * 101 + y);
  }
  return null;
}

