function outerTrees(trees) {
  const n = trees.length;
  if (n === 1) return [trees[0]];
  const onFence = new Array(n).fill(false);
  // The segment i-j is on the fence when all trees lie on one side of its line (or on it).
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const [ax, ay] = trees[i], [bx, by] = trees[j];
      let left = 0, right = 0;
      const side = trees.map(([x, y]) => (bx - ax) * (y - ay) - (by - ay) * (x - ax));
      for (const s of side) { if (s > 0) left++; else if (s < 0) right++; }
      if (left > 0 && right > 0) continue;
      for (let k = 0; k < n; k++) {
        const [x, y] = trees[k];
        if (side[k] === 0 && x >= Math.min(ax, bx) && x <= Math.max(ax, bx) && y >= Math.min(ay, by) && y <= Math.max(ay, by)) onFence[k] = true;
      }
    }
  }
  return trees.filter((_, k) => onFence[k]);
}

