function generate(rand, size) {
  // Distinct positions: a partial shuffle of every cell in the [0, span] square.
  const pick = (span, count) => {
    const cells = [];
    for (let x = 0; x <= span; x++) for (let y = 0; y <= span; y++) cells.push([x, y]);
    for (let i = 0; i < count; i++) {
      const j = i + Math.floor(rand() * (cells.length - i));
      [cells[i], cells[j]] = [cells[j], cells[i]];
    }
    return cells.slice(0, count);
  };
  if (size === 'large') {
    const span = rand() < 0.5 ? 100 : 44;
    return [pick(span, Math.min(2000, (span + 1) * (span + 1)))];
  }
  const shape = rand();
  if (shape < 0.15) {
    // Every tree on one straight line: horizontal, vertical or diagonal.
    const n = 1 + Math.floor(rand() * 6);
    const kind = Math.floor(rand() * 3);
    const start = Math.floor(rand() * 5);
    const steps = pick(8, n).map(([x]) => x);
    const unique = [...new Set(steps)];
    return [unique.map(t => kind === 0 ? [t, start] : kind === 1 ? [start, t] : [t, t])];
  }
  const span = 2 + Math.floor(rand() * 5);
  const n = Math.min(1 + Math.floor(rand() * 11), (span + 1) * (span + 1));
  const trees = pick(span, n);
  if (rand() < 0.1) for (const tree of trees) { tree[0] = 100 - tree[0]; tree[1] = 100 - tree[1]; }
  return [trees];
}
